          "stage": "price",
          "focus": "准确价格",
          "sentences": [
            {
              "display_text": "价格方面，这只杯子售价是四十九元。",
              "spoken_text": "价格方面，这只杯子售价是四十九元。",
              "kind": "product_claim",
              "fact_ids": ["PRICE"]
