        {
          "stage": "cta",
          "focus": "自然购买引导",
          "sentences": [
            {
              "display_text": "如果你正好缺一只日常用的杯子，可以看看这只米白陶瓷马克杯。",
              "spoken_text": "如果你正好缺一只日常用的杯子，可以看看这只米白陶瓷马克杯。",
              "kind": "product_claim",
              "fact_ids": ["NAME", "SELLING"]
